"""Stock levels keyed by SKU. Quantities are non-negative integers."""


def available(stock, sku):
    """Units of sku currently available; unknown SKUs have none."""
    return stock.get(sku, 0)


def reserve(stock, sku, quantity):
    """Remove quantity units of sku from stock; raise ValueError if too few are available."""
    if quantity <= 0:
        raise ValueError("quantity must be positive")
    if available(stock, sku) < quantity:
        raise ValueError(f"only {available(stock, sku)} of {sku} available")
    stock[sku] = available(stock, sku) - quantity


def release(stock, sku, quantity):
    """Return quantity previously reserved units of sku to stock."""
    if quantity <= 0:
        raise ValueError("quantity must be positive")
    stock[sku] = available(stock, sku) + quantity

compliant.tests/test_release.py:
import unittest

from inventory.stock import available, release, reserve


class Release(unittest.TestCase):
    def test_release_restores_reserved_units(self):
        stock = {"tea": 5}
        reserve(stock, "tea", 2)
        release(stock, "tea", 2)
        self.assertEqual(available(stock, "tea"), 5)

    def test_release_refuses_non_positive_quantity(self):
        with self.assertRaises(ValueError):
            release({"tea": 1}, "tea", 0)

